{
  "hypotheses": [
    {
      "stance": "bull",
      "mechanism": "若 UPS 配合最大客戶減量整併美國分揀班次與配送路線，相較維持原網路，可減少閒置工時與運能成本，支撐營業利益率。約 10 億美元是多年節省目標，2025 年可實現多少節省仍未知。",
      "target": "UPS",
      "horizon": "2026-03-31",
      "catalyst": "UPS 於 2025 年 1 月 30 日宣布重整美國網路。營運催化因素是其後實際調整班次與路線，全年指引提供比較基準。",
      "prediction": "截至 2026 年 3 月 31 日，查核 UPS 第四季暨全年業績公告，預期 2025 全年合併營業利益率按指引同口徑達 10.8% 或以上。此為獲利代理指標，無法單獨辨識美國網路節省的貢獻。",
      "invalidation": "同一查核期限內，若 UPS 公布的 2025 全年同口徑合併營業利益率低於 10.8%，則獲利預測失效。若未揭露同口徑數字，結果待驗。",
      "claim_ids": ["fact:ups-q4:network", "fact:ups-q4:volume", "fact:ups-q4:guidance"]
    },
    {
      "stance": "bear",
      "mechanism": "若最大客戶在 2025 年縮量快於指引所隱含的進度，相較維持原配送量，UPS 可計費的配送件數會更少。若其他業務新增營收不足以填補缺口，全年營收可能低於指引。客戶減量時程與每件收入均未揭露，無法估算缺口。",
      "target": "UPS",
      "horizon": "2026-03-31",
      "catalyst": "2025 年 1 月 30 日披露的原則協議以 2026 年下半年為減量目標期。研究期內的催化因素是客戶若提前減少實際交運件數，協議本身尚未造成可核實的營收流失。",
      "prediction": "截至 2026 年 3 月 31 日，查核 UPS 第四季暨全年業績公告，預期 2025 全年合併營收低於指引中心值 890 億美元。此為總營收代理指標，無法據以歸因於單一客戶。",
      "invalidation": "同一查核期限內，若 UPS 公布的 2025 全年合併營收達 890 億美元或以上，則營收預測失效。若尚未公布，結果待驗。",
      "claim_ids": ["fact:ups-q4:volume", "fact:ups-q4:guidance"]
    }
  ],
  "assessment": {
    "thesis": "UPS 縮減最大客戶包裹量後，若美國網路能隨件量調整班次與路線，即使可計費配送收入承壓，仍可能守住全年營業利益率。",
    "key_gap": "2025 年網路重整的實現淨節省，能否抵銷最大客戶減量所流失的利益？若 UPS 未量化兩者，精確歸因需非公開的客戶配送收入、可避免成本與重整費用紀錄。",
    "next_check": "在 2025 年底後至 2026 年 3 月 31 日間查核 UPS 第四季暨全年業績公告，比對全年營收及同口徑營業利益率與 2025 年 1 月 30 日指引，並查看公司是否量化當年已實現的節省。",
    "evidence_limits": [
      {
        "evidence_id": "ups-q4:volume",
        "limit": "原則協議訂出至 2026 年下半年減量逾 50% 的目標，完成期晚於研究期限；2025 年實際減量未揭露。SurePost 自 2025 年 1 月 1 日起全數自配是已披露的營運變動，其件數與成本影響未知。"
      },
      {
        "evidence_id": "ups-q4:network",
        "limit": "UPS 已宣布重整美國網路，約 10 億美元屬多年流程重設目標。公告未提供 2025 年實現額或扣除重整費用後的淨效益。"
      },
      {
        "evidence_id": "ups-q4:guidance",
        "limit": "約 890 億美元營收與約 10.8% 營業利益率均為 2025 全年合併指引。公告未拆出客戶減量與美國網路重整各自的影響。"
      }
    ],
    "public_checks": [
      {
        "metric": "美國網路已完成的班次或路線整併，以及 UPS 若有揭露的當期實現節省額。",
        "source_to_watch": "UPS 投資人關係季度業績公告與法說會公開資料。",
        "window": "自宣布重整後逐季追蹤，至 2026 年 3 月 31 日檢視涵蓋 2025 全年的更新。",
        "impact_on_thesis": "已完成整併支持成本機制開始運作。若公司同時揭露節省額與執行費用，才可判斷當年淨效益。僅重申多年目標時，實現程度仍待查。",
        "evidence_ids": ["ups-q4:network"]
      },
      {
        "metric": "最大客戶實際交運量的減幅或進度，以及 UPS 是否因此調整全年營收指引。",
        "source_to_watch": "UPS 投資人關係業績公告中對原則協議及全年指引的更新。",
        "window": "從 2025 年 1 月 30 日公告後至 2026 年 3 月 31 日，查看各季對 2025 年交運量及營收的說明。",
        "impact_on_thesis": "若 UPS 明示減量快於原先預期且因此下修營收指引，則提前縮量拖累營收的可信度上升。僅見合併營收下修時，客戶歸因仍待查。",
        "evidence_ids": ["ups-q4:volume", "ups-q4:guidance"]
      }
    ],
    "supply_chain": [],
    "trade_opportunities": []
  }
}
